@inline function _nas_taper_edge_lengths(coords::AbstractMatrix)
    l12 = hypot(coords[2, 1] - coords[1, 1], coords[2, 2] - coords[1, 2])
    l43 = hypot(coords[3, 1] - coords[4, 1], coords[3, 2] - coords[4, 2])
    l23 = hypot(coords[3, 1] - coords[2, 1], coords[3, 2] - coords[2, 2])
    l14 = hypot(coords[4, 1] - coords[1, 1], coords[4, 2] - coords[1, 2])
    return l12, l43, l23, l14
end

@inline function _nas_taper_smoothstep(a::Float64, b::Float64, x::Float64)
    b <= a && return x >= b ? 1.0 : 0.0
    t = clamp((x - a) / (b - a), 0.0, 1.0)
    return t * t * (3.0 - 2.0 * t)
end

function _nas_taper_metrics(coords::AbstractMatrix, Cb::AbstractMatrix)
    l12, l43, l23, l14 = _nas_taper_edge_lengths(coords)
    lx = 0.5 * (l12 + l43)
    ly = 0.5 * (l23 + l14)
    lx > 1e-30 && ly > 1e-30 || return nothing
    aspect = lx / ly
    aspect >= 1.0 || return nothing
    taper_ratio = min(l23, l14) / max(max(l23, l14), 1e-30)
    deficit = 1.0 - taper_ratio
    D11 = Float64(Cb[1, 1])
    D22 = Float64(Cb[2, 2])
    D11 > 0.0 && D22 > 0.0 || return nothing
    alpha = (ly / lx) * (D11 / D22)^(1 / 4)
    return (; aspect, taper_ratio, deficit, alpha)
end

function nastran_taper_kg_synth_supported(coords::AbstractMatrix,
                                          Cb::AbstractMatrix;
                                          aspect_min::Float64=2.5,
                                          aspect_max::Float64=14.0,
                                          taper_deficit_min::Float64=1.0e-6,
                                          taper_deficit_max::Float64=0.30)
    metrics = _nas_taper_metrics(coords, Cb)
    metrics === nothing && return false
    return aspect_min <= metrics.aspect <= aspect_max &&
           taper_deficit_min <= metrics.deficit <= taper_deficit_max
end

function _nas_taper_feature_value(feature::Symbol, alpha::Float64, d::Float64)
    alpha2 = alpha * alpha
    alpha3 = alpha2 * alpha
    alpha4 = alpha2 * alpha2
    d2 = d * d
    d3 = d2 * d
    if feature === :one
        return 1.0
    elseif feature === :alpha
        return alpha
    elseif feature === :alpha2
        return alpha2
    elseif feature === :alpha3
        return alpha3
    elseif feature === :alpha4
        return alpha4
    elseif feature === :d
        return d
    elseif feature === :d2
        return d2
    elseif feature === :d3
        return d3
    elseif feature === :alpha_d
        return alpha * d
    elseif feature === :alpha_d2
        return alpha * d2
    elseif feature === :alpha_d3
        return alpha * d3
    elseif feature === :alpha2_d
        return alpha2 * d
    elseif feature === :alpha2_d2
        return alpha2 * d2
    elseif feature === :alpha2_d3
        return alpha2 * d3
    elseif feature === :alpha3_d
        return alpha3 * d
    elseif feature === :alpha3_d2
        return alpha3 * d2
    elseif feature === :alpha3_d3
        return alpha3 * d3
    elseif feature === :alpha4_d
        return alpha4 * d
    elseif feature === :alpha4_d2
        return alpha4 * d2
    elseif feature === :alpha4_d3
        return alpha4 * d3
    end
    error("unsupported tapered Kg synthesis feature: $feature")
end

function _nas_taper_raw_features(branch::Symbol, alpha::Float64, d::Float64)
    features = _NAS_TAPER_KG_FEATURES[branch]
    return ntuple(i -> _nas_taper_feature_value(features[i], alpha, d), length(features))
end

function _nas_taper_eval_component!(K12::AbstractMatrix, branch::Symbol,
                                    comp::Symbol, scale::Float64,
                                    alpha::Float64, d::Float64)
    raw = _nas_taper_raw_features(branch, alpha, d)
    scaling = _NAS_TAPER_KG_SCALING[(branch, comp)]
    coeffs = _NAS_TAPER_KG_COEFFS[(branch, comp)]
    x = ntuple(i -> (raw[i] - scaling[i][1]) / scaling[i][2], length(raw))
    @inbounds for item in coeffs
        row = Int(item[1])
        col = Int(item[2])
        fidx = Int(item[3])
        K12[row, col] += scale * x[fidx] * item[4]
    end
    return K12
end

function _nas_taper_branch_weights(aspect::Float64)
    if aspect < 4.5
        return ((:low, 1.0),)
    elseif aspect <= 8.0
        return ((:transition, 1.0),)
    elseif aspect < 10.0
        t = _nas_taper_smoothstep(8.0, 10.0, aspect)
        return ((:transition, 1.0 - t), (:high, t))
    end
    return ((:high, 1.0),)
end

@inline function _nas_taper_corner_index(x::Float64, y::Float64, cx::Float64, cy::Float64)
    if x <= cx
        return y <= cy ? 1 : 3
    else
        return y <= cy ? 2 : 4
    end
end

function _nas_taper_basis_index_by_local_node(coords::AbstractMatrix)
    xmin = minimum(@view coords[:, 1])
    xmax = maximum(@view coords[:, 1])
    ymin = minimum(@view coords[:, 2])
    ymax = maximum(@view coords[:, 2])
    cx = 0.5 * (xmin + xmax)
    cy = 0.5 * (ymin + ymax)
    return ntuple(i -> _nas_taper_corner_index(
            Float64(coords[i, 1]), Float64(coords[i, 2]), cx, cy,
        ), 4)
end

function geometric_stiffness_quad4_nastran_taper_synth(coords::AbstractMatrix,
                                                        sigma_mem::AbstractVector,
                                                        h::Float64,
                                                        Cb::AbstractMatrix)
    Kg = zeros(24, 24)
    h > 1e-30 || return Kg
    metrics = _nas_taper_metrics(coords, Cb)
    metrics === nothing && return Kg
    K12 = zeros(12, 12)
    resultants = (Float64(sigma_mem[1]) * h, Float64(sigma_mem[2]) * h, Float64(sigma_mem[3]) * h)
    for (branch, weight) in _nas_taper_branch_weights(metrics.aspect)
        _nas_taper_eval_component!(K12, branch, :nxx, weight * resultants[1], metrics.alpha, metrics.deficit)
        _nas_taper_eval_component!(K12, branch, :nyy, weight * resultants[2], metrics.alpha, metrics.deficit)
        _nas_taper_eval_component!(K12, branch, :nxy, weight * resultants[3], metrics.alpha, metrics.deficit)
    end
    tdofs = (1, 2, 3, 7, 8, 9, 13, 14, 15, 19, 20, 21)
    basis_by_local = _nas_taper_basis_index_by_local_node(coords)
    @inbounds for a in 1:12, b in 1:12
        local_node_a = div(a - 1, 3) + 1
        local_node_b = div(b - 1, 3) + 1
        comp_a = (a - 1) % 3 + 1
        comp_b = (b - 1) % 3 + 1
        basis_a = (basis_by_local[local_node_a] - 1) * 3 + comp_a
        basis_b = (basis_by_local[local_node_b] - 1) * 3 + comp_b
        Kg[tdofs[a], tdofs[b]] = 0.5 * (K12[basis_a, basis_b] + K12[basis_b, basis_a])
    end
    return Kg
end

function geometric_stiffness_quad4_nastran_taper_synth(coords::AbstractMatrix,
                                                        sigma_mem_gp::AbstractMatrix,
                                                        h::Float64,
                                                        Cb::AbstractMatrix)
    size(sigma_mem_gp, 2) >= 3 || return zeros(24, 24)
    inv_ngp = 1.0 / max(size(sigma_mem_gp, 1), 1)
    sigma_mem = [
        sum(@view sigma_mem_gp[:, 1]) * inv_ngp,
        sum(@view sigma_mem_gp[:, 2]) * inv_ngp,
        sum(@view sigma_mem_gp[:, 3]) * inv_ngp,
    ]
    return geometric_stiffness_quad4_nastran_taper_synth(coords, sigma_mem, h, Cb)
end
